const g = { A: [['B', 4], ['C', 1]], B: [['D', 1]], C: [['B', 2], ['D', 5]], D: [] };
const dist = { A: 0, B: Infinity, C: Infinity, D: Infinity };
const pq = [[0, 'A']];
while (pq.length) {
  pq.sort((a, b) => a[0] - b[0]);
  const [d, u] = pq.shift();
  if (d > dist[u]) continue;
  for (const [v, w] of g[u]) if (d + w < dist[v]) { dist[v] = d + w; pq.push([dist[v], v]); }
}
